WITH remaining_keys AS (SELECT supplier_id, id FROM products EXCEPT DISTINCT SELECT supplier_id, id FROM products WHERE ARRAY_CONTAINS(tags, 'new')), kept_rows AS (SELECT s.* FROM products s JOIN remaining_keys k ON s.supplier_id = k.supplier_id AND s.id = k.id) SELECT DATE_TRUNC('YEAR', launch_date) AS year_start, CASE WHEN cost >= 560 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, AVG(stock_qty) FILTER (WHERE category = 'Electronics') AS electronics_avg_stock_qty, SIZE(COLLECT_SET(brand)) AS num_brands, SORT_ARRAY(COLLECT_SET(category)) AS category_list, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN category = 'Home' THEN 1 END), 0), 2) AS cost_per_home, COUNT_IF(brand = 'Stark') AS stark_events FROM kept_rows GROUP BY CUBE (DATE_TRUNC('YEAR', launch_date), CASE WHEN cost >= 560 THEN 'PREMIUM' ELSE 'STANDARD' END)
